esqlQuery.esql:
TS metrics-temporal.cloud_metrics.otel-*
// activity_task_timeout_count counts per-attempt timeouts by timeout_type
// These may be retried; persistent rates indicate systemic issues
| STATS timeout_rate = SUM(AVG_OVER_TIME(metrics.temporal_cloud_v1_activity_task_timeout_count))
    BY attributes.temporal_namespace, attributes.temporal_task_queue, attributes.timeout_type
// Alert threshold: 0.05/s (~3 per minute); tune for your workload
| WHERE timeout_rate > 0.05
| SORT timeout_rate DESC
| LIMIT 20
